314	```javascript
315	// Words whose trailing period does not end a sentence. Compared lower-case and
316	// without any opening bracket or quote. "U.S.A." style initialisms are not
317	// listed: they usually do end a sentence when they come last, and guessing
318	// otherwise would trade one error for another.
319	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
320	
321	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
322	// only where whitespace or the end of the text follows. Requiring that keeps
323	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
324	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
325	
326	function endsWithAbbreviation(before) {
327	  const last = before.match(/(\S+)$/);
328	  if (last === null) {
329	    return false;
330	  }
331	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
332	  return ABBREVIATIONS.has(word);
333	}
334	
335	/**
336	 * Count the sentences in a piece of text.
337	 *
338	 * A sentence is a stretch of text containing at least one word and ending at a
339	 * terminator run, or at the end of the text. A lone period after a known
340	 * abbreviation does not end a sentence.
341	 *
342	 * @param {string} text
343	 * @returns {number}
344	 */
345	function sentenceCount(text) {
346	  assertText('sentenceCount', text);
347	  let count = 0;
348	  let start = 0;
349	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
350	    const before = text.slice(start, match.index);
351	    if (match[1] === '.' && endsWithAbbreviation(before)) {
352	      continue;
353	    }
354	    if (tokenize(before).length > 0) {
355	      count += 1;
356	    }
357	    start = match.index + match[0].length;
358	  }
359	  if (tokenize(text.slice(start)).length > 0) {
360	    count += 1;
361	  }
362	  return count;
363	}
364	
365	module.exports = { wordCount, sentenceCount };
366	```
