496	/**
497	 * List the most frequent words in a piece of text.
498	 *
499	 * Words are lower-cased, typographic apostrophes are folded to straight ones,
500	 * and stop words are skipped. Entries are ordered by count (highest first),
501	 * then alphabetically, so the result is deterministic.
502	 *
503	 * @param {string} text
504	 * @param {number} n How many entries to return; a non-negative integer.
505	 * @returns {Array<{word: string, count: number}>}
506	 */
507	function topWords(text, n) {
508	  assertText('topWords', text);
509	  if (!Number.isInteger(n) || n < 0) {
510	    throw new RangeError(`topWords: n must be a non-negative integer, received ${String(n)}`);
511	  }
512	  const counts = new Map();
513	  for (const token of tokenize(text)) {
514	    const word = token.toLowerCase().replace(/’/g, "'");
515	    if (STOP_WORDS.has(word)) {
516	      continue;
517	    }
518	    counts.set(word, (counts.get(word) ?? 0) + 1);
519	  }
520	  return [...counts]
521	    .map(([word, count]) => ({ word, count }))
522	    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
523	    .slice(0, n);
524	}
